import stringUtil from 'src/utils/string';
import { readOnlyDocStatus } from 'src/constants';
import taxFieldsHelper from 'src/utils/taxFieldsHelper';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';

export default {
  mixins: [stringUtil],
  methods: {
    prepareLayoutForTemplate() {
      if (!this.formLayout || !Array.isArray(this.formLayout)) {
        return;
      }

      const calculatorFieldsDef =
        taxFieldsHelper.methods.getCalculatorFieldsDef();

      for (const group of this.formLayout) {
        if (!group || !group.rows) continue;
        let total_fields = 0;

        if (!Array.isArray(group.rows)) {
          group.is_hidden = true;
          continue;
        }

        for (const [index, subRow] of group.rows.entries()) {
          if (subRow.fieldType === formBuilderInputTypes.SUB_GROUP) {
            const subGroups = subRow.rows;
            for (let subgroup of subGroups) {
              if (calculatorFieldsDef.hasOwnProperty(subgroup.field_name)) {
                Object.assign(
                  subgroup,
                  calculatorFieldsDef[subgroup.field_name],
                );
                Object.assign(
                  this.formBuilderConfigModel[subgroup.field_name],
                  calculatorFieldsDef[subgroup.field_name],
                );
              } else if (
                calculatorFieldsDef.hasOwnProperty(subgroup.parent_field_name)
              ) {
                let formula = JSON.parse(
                  JSON.stringify(
                    calculatorFieldsDef[subgroup.parent_field_name],
                  ),
                );

                const endingString = this.getStringLastPart(
                  subgroup.field_name,
                  '__',
                );
                formula.calculator_formula = formula.calculator_formula
                  .split(']')
                  .join('__' + endingString + ']');

                Object.assign(subgroup, formula);
                Object.assign(
                  this.formBuilderConfigModel[subgroup.field_name],
                  formula,
                );
              }
            }
          } else if (calculatorFieldsDef.hasOwnProperty(subRow.field_name)) {
            Object.assign(subRow, calculatorFieldsDef[subRow.field_name]);
            Object.assign(
              this.formBuilderConfigModel[subRow.field_name],
              calculatorFieldsDef[subRow.field_name],
            );
          }

          total_fields++;

          if (
            (subRow.visibile !== undefined && subRow.visibile === false) ||
            subRow.is_hidden
          ) {
            total_fields--;
          }
        }

        group.is_hidden = total_fields < 1 ? true : false;
      }
    },
    isButtonToggleDisable(status) {
      if (readOnlyDocStatus.includes(status)) {
        return true;
      }
      return false;
    },
    calculateRowColSize(rowSize) {
      if (rowSize > 1) {
        return 100 / rowSize;
      }

      return 100;
    },
  },
};
