import type { dynamicObj } from 'src/pages/assets';

export default {
  methods: {
    getCalculatorFieldsDef() {
      const calculator_fields = {} as dynamicObj;
      calculator_fields['net_amount'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForNetAmount(''),
      };

      calculator_fields['tax_amount'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForTaxAmount(''),
      };

      calculator_fields['tax_rate'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForTaxRate(''),
      };

      calculator_fields['net_amount_2'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForNetAmount('_2'),
      };

      calculator_fields['tax_amount_2'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForTaxAmount('_2'),
      };

      calculator_fields['tax_rate_2'] = {
        calculator: true,
        calculator_formula: this.generateFormulaForTaxRate('_2'),
      };

      return calculator_fields;
    },

    generateFormulaForNetAmount(postfix: string) {
      return '[tax_amount' + postfix + '] * 100 / [tax_rate' + postfix + ']';
    },

    generateFormulaForTaxAmount(postfix: string) {
      return '[net_amount' + postfix + '] * [tax_rate' + postfix + '] / 100';
    },

    generateFormulaForTaxRate(postfix: string) {
      return '[tax_amount' + postfix + '] * 100 / [net_amount' + postfix + ']';
    },
  },
};
